async function getTemp(lat, lon, fetchFn = fetch) {
  const response = await fetchFn(`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m`)
  if (!response.ok) throw new Error(`HTTP ${response.status}`)
  const data = await response.json()
  return data.current.temperature_2m
}
async function allTemps(cities, fetchFn = fetch) {
  const pairs = await Promise.all(Object.entries(cities).map(async ([name, [lat, lon]]) => [name, await getTemp(lat, lon, fetchFn)]))
  return Object.fromEntries(pairs)
}
async function someTemps(cities, fetchFn = fetch) {
  const entries = Object.entries(cities)
  const results = await Promise.allSettled(entries.map(([, [lat, lon]]) => getTemp(lat, lon, fetchFn)))
  return Object.fromEntries(entries.map(([name], i) => [name, results[i].status === "fulfilled" ? results[i].value : null]))
}
function hottest(temps) {
  let best = null
  for (const [name, t] of Object.entries(temps)) {
    if (t !== null && (best === null || t > temps[best])) best = name
  }
  return best
}
